<div class="mb-4"><label for="user-<?= e($fieldName) ?>"><?= e($label) ?><?= $required ? ' *' : '' ?></label><input class="form-control" type="password" id="user-<?= e($fieldName) ?>" name="<?= e($fieldName) ?>" autocomplete="<?= $fieldName === 'current_password' ? 'current-password' : 'new-password' ?>" <?= $fieldName === 'current_password' ? 'maxlength="1024"' : 'minlength="12" maxlength="72"' ?> <?= $required ? 'required' : '' ?> aria-describedby="help-<?= e($fieldName) ?><?= isset($editorErrors[$fieldName]) ? ' error-' . e($fieldName) : '' ?>" <?= isset($editorErrors[$fieldName]) ? 'aria-invalid="true"' : '' ?>><p class="form-text" id="help-<?= e($fieldName) ?>"><?= $fieldName === 'current_password' ? 'Confirma tu identidad antes de cambiar la contraseña.' : 'Al menos 12 caracteres. Puedes utilizar una frase; máximo 72 bytes.' ?></p><?php if (isset($editorErrors[$fieldName])): ?><p class="editor-error" id="error-<?= e($fieldName) ?>"><?= e($editorErrors[$fieldName]) ?></p><?php endif ?></div>
